// Extract data from webhook
const body = $input.first().json.body;

return {
  manuscriptId: body.manuscriptId,
  manuscriptTitle: body.manuscriptTitle,
  authorName: body.authorName,

  // Assessment answers
  publishing_goal: body.assessmentAnswers.publishing_goal,
  experience: body.assessmentAnswers.experience,
  platforms: JSON.stringify(body.assessmentAnswers.platforms || []),
  timeline: body.assessmentAnswers.timeline,
  formats: JSON.stringify(body.assessmentAnswers.formats || [])
};

// Combine all data for plan generation
const parsedData = $('Parse Assessment Data').first().json;
const manuscriptData = $('Get Manuscript Data').first().json;
const savedData = $('Save Assessment Answers').first().json;

// Parse platforms array from JSONB
let platformsList = 'Not specified';
if (savedData.platforms) {
  try {
    const platforms = typeof savedData.platforms === 'string' 
      ? JSON.parse(savedData.platforms) 
      : savedData.platforms;
    if (platforms && platforms.length > 0) {
      platformsList = platforms.join(', ');
    }
  } catch(e) {
    console.error('Error parsing platforms:', e);
    platformsList = 'Not specified';
  }
}

// Parse formats array from JSONB
let formatsList = 'Not specified';
if (savedData.formats) {
  try {
    const formats = typeof savedData.formats === 'string'
      ? JSON.parse(savedData.formats)
      : savedData.formats;
    if (formats && formats.length > 0) {
      formatsList = formats.join(', ');
    }
  } catch(e) {
    console.error('Error parsing formats:', e);
    formatsList = 'Not specified';
  }
}

return {
  manuscriptId: parsedData.manuscriptId,
  manuscriptTitle: manuscriptData.manuscript_title,
  genre: manuscriptData.genre,
  wordCount: manuscriptData.current_word_count,
  authorName: manuscriptData.author_first_name,
  authorEmail: manuscriptData.author_email,

  publishing_goal: savedData.publishing_goal || 'Not specified',
  experience: savedData.experience || 'Not specified',
  platforms: platformsList,
  timeline: savedData.timeline || 'Not specified',
  formats: formatsList
};

// Get AI output - LangChain uses .text field
const aiOutput = $('Generate Publishing Plan').first().json;
const planText = aiOutput.text || aiOutput.output || aiOutput.response || '';

console.log('🔍 AI Output keys:', Object.keys(aiOutput));
console.log('📝 Plan text found in field:', aiOutput.text ? '.text' : (aiOutput.output ? '.output' : (aiOutput.response ? '.response' : 'NONE')));
console.log('📝 Plan length:', planText.length);

if (!planText) {
  throw new Error('No plan text found in AI output. Available keys: ' + Object.keys(aiOutput).join(', '));
}

const manuscriptId = $('Prepare Plan Data').first().json.manuscriptId;

// Escape single quotes for SQL
const escapedPlan = planText.replace(/'/g, "''");

return {
  query: `UPDATE publishing_progress
SET 
  publishing_plan = '${escapedPlan}',
  current_step = 'cover-design',
  updated_at = NOW()
WHERE manuscript_id = '${manuscriptId}'
RETURNING *;`,
  planText: planText,
  manuscriptId: manuscriptId
};

// Get current date
const now = new Date();
const analysisDate = now.toLocaleDateString('en-US', { 
  year: 'numeric', 
  month: 'long', 
  day: 'numeric' 
});

const preparedData = $('Prepare Plan Data').first().json;
const aiOutput = $('Generate Publishing Plan').first().json;

// LangChain uses .text field
const planMarkdown = aiOutput.text || aiOutput.output || aiOutput.response || '';

console.log('🔍 AI Output keys:', Object.keys(aiOutput));
console.log('📝 Plan text length:', planMarkdown.length);
console.log('📝 First 100 chars:', planMarkdown.substring(0, 100));

if (!planMarkdown) {
  throw new Error('No plan text found in AI output. Available keys: ' + Object.keys(aiOutput).join(', '));
}

// Convert markdown to HTML (basic conversion)
const planHtml = planMarkdown
  .replace(/^# (.*$)/gm, '<h1>$1</h1>')
  .replace(/^## (.*$)/gm, '<h2>$1</h2>')
  .replace(/^### (.*$)/gm, '<h3>$1</h3>')
  .replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>')
  .replace(/^\* (.*$)/gm, '<li>$1</li>')
  .replace(/^- (.*$)/gm, '<li>$1</li>')
  .replace(/\n\n/g, '</p><p>')
  .replace(/^(?!<[h|l|p])(.*$)/gm, '<p>$1</p>');

return {
  manuscriptId: preparedData.manuscriptId,
  authorName: preparedData.authorName,
  authorEmail: preparedData.authorEmail,
  manuscriptTitle: preparedData.manuscriptTitle,
  analysisDate: analysisDate,
  totalWordCount: String(preparedData.wordCount),
  publishingGoal: preparedData.publishing_goal || 'not specified',
  experienceLevel: preparedData.experience || 'not specified',
  timeline: preparedData.timeline || 'not specified',
  budgetRange: '',
  planHtml: planHtml
};

// Get author info for personalized response
const preparedData = $('Prepare Plan Data').first().json;
const pdfUrl = $('Save PDF URL').first().json.plan_pdf_url;

const response = `🎉 Your publishing plan is ready!

I've created a comprehensive strategy for "${preparedData.manuscriptTitle}" based on your goals. You can view the full plan by clicking the button above, and I've sent a copy to ${preparedData.authorEmail}.

Now let's get started with the exciting part - creating your cover designs! Just say "create my cover" and I'll generate four professional concepts for you to choose from.

What would you like to work on first?`;

return {
  response: response,
  success: true,
  planPdfUrl: pdfUrl
};
